FUNCTION_BLOCK FB_S02
VAR_INPUT
    FwdBtn : BOOL;
    RevBtn : BOOL;
    MaintKey : BOOL;
    EStop_NC : BOOL;
END_VAR
VAR_OUTPUT
    MotorFwd : BOOL := FALSE;
    MotorRev : BOOL := FALSE;
    RunLamp : BOOL := FALSE;
    Status : WORD := WORD#16#0000;
END_VAR
VAR
    StartupScans : UINT := UINT#2;
    LastDirection : INT := INT#0;
    RequestedDirection : INT := INT#0;
    OffHistory : UINT := UINT#0;
    DeadRemaining : UINT := UINT#0;
    MaintPhase : UINT := UINT#0;
END_VAR

(*
    待审语义冲突：
    1. 要求1的即时启动与 C10 的 G[0,1] 禁止输出冲突。
       此实现按 C10 的闭区间解释，前两个调用周期禁止电机输出。
    2. 两按钮同时有效时，要求1未定义仲裁；同时启动违反 K1。
       此实现安全停机，不擅自赋予某一方向优先级。
    3. C9 在急停后仍然有效，因此清空死区计时不能同时删除
       最近方向输出的历史。急停清零 DeadRemaining；
       OffHistory 独立保存连续断开历史，以维持 C9。
    正常态 RunLamp 按运行指示灯含义显示任一电机输出。
    未经真实编译器验证，未声称通过逐周期功能测试。

    时间约定：
    每次调用为20 ms。换向断开当周期不计为已过去20 ms。
    连续断开十个完整周期后才允许相反方向。
*)

(* 根据上一周期实际输出累计连续断开历史，最大200 ms。 *)
IF MotorFwd OR MotorRev THEN
    OffHistory := UINT#0;
ELSIF OffHistory < UINT#10 THEN
    OffHistory := OffHistory + UINT#1;
END_IF;

RequestedDirection := INT#0;
IF FwdBtn AND NOT RevBtn THEN
    RequestedDirection := INT#1;
ELSIF RevBtn AND NOT FwdBtn THEN
    RequestedDirection := INT#2;
END_IF;

(* 每周期默认安全断开，只有通过所有联锁才赋值启动。 *)
MotorFwd := FALSE;
MotorRev := FALSE;
RunLamp := FALSE;
Status := WORD#16#0000;

(* 检修闪灯：50个扫描一个周期，25周期灭、25周期亮。 *)
IF MaintKey THEN
    RunLamp := MaintPhase >= UINT#25;
    IF MaintPhase >= UINT#49 THEN
        MaintPhase := UINT#0;
    ELSE
        MaintPhase := MaintPhase + UINT#1;
    END_IF;
ELSE
    MaintPhase := UINT#0;
END_IF;

(* 安全优先级：急停 > 检修 > 上电抑制 > 方向控制。 *)
IF NOT EStop_NC THEN
    DeadRemaining := UINT#0;
    Status := WORD#16#8202;

ELSIF MaintKey THEN
    DeadRemaining := UINT#0;
    Status := WORD#16#8201;

ELSIF StartupScans > UINT#0 THEN
    DeadRemaining := UINT#0;

ELSIF RequestedDirection = INT#0 THEN
    DeadRemaining := UINT#0;

ELSIF (LastDirection <> INT#0)
      AND (RequestedDirection <> LastDirection)
      AND (OffHistory < UINT#10) THEN
    DeadRemaining := UINT#10 - OffHistory;
    Status := WORD#16#8203;

ELSE
    DeadRemaining := UINT#0;

    IF RequestedDirection = INT#1 THEN
        MotorFwd := TRUE;
        LastDirection := INT#1;
    ELSIF RequestedDirection = INT#2 THEN
        MotorRev := TRUE;
        LastDirection := INT#2;
    END_IF;
END_IF;

IF StartupScans > UINT#0 THEN
    StartupScans := StartupScans - UINT#1;
END_IF;

IF NOT MaintKey THEN
    RunLamp := MotorFwd OR MotorRev;
END_IF;

END_FUNCTION_BLOCK
